import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>PNG ve WebP, web görsellerinin iki ağır sıkletidir. İkisi de saydamlığı destekler, ikisi de keskin görünür; ama dosya boyutunda ve uyumlulukta birbirinden ayrılırlar.</p>\n<p>Doğru seçim, görselin nerede kullanılacağına bağlıdır. Logo için doğru olan, fotoğraf için yanlış olabilir; web için doğru olan, e-posta için yanlış olabilir.</p>\n<p>Bu yazı iki formatı saydamlık, boyut, metin netliği, fotoğraf kalitesi ve destek açısından karşılaştırıyor; sonunda hangisini ne zaman kullanacağınız belli olacak.</p>\n<h2 id=\"png-at-a-glance\">PNG'ye bir bakışta</h2>\n<p>PNG 1996'dan beri var ve her yerde destekleniyor. Kayıpsız sıkıştırma kullanır; kaydedilen her piksel, açıldığında birebir aynıdır.</p>\n<p>PNG'nin en büyük gücü saydamlığıdır. Alfa kanalı sayesinde logolar her arka plan üzerinde temiz görünür.</p>\n<p>Zayıf yanı dosya boyutudur. PNG dosyaları büyüktür; özellikle fotoğraf benzeri görsellerde boyut hızla artar.</p>\n<h2 id=\"webp-at-a-glance\">WebP'ye bir bakışta</h2>\n<p>WebP, Google tarafından 2010'da tanıtıldı. Kayıplı ve kayıpsız sıkıştırmayı bir arada sunar; saydamlığı da destekler.</p>\n<p>WebP'nin gücü verimliliktir. Aynı görseli PNG'den yüzde 25-35 daha küçük saklar; fotoğraflarda kazanç daha da büyür.</p>\n<p>Zayıf yanı uyumluluktur. Modern tarayıcılar destekler ama bazı eski sistemler, formlar ve yazılımlar WebP'yi tanımaz.</p>\n<h2 id=\"transparency-compared\">Saydamlık: neredeyse beraberlik</h2>\n<p>İki format da tam alfa saydamlığı sunar. Saydam logo iki formatta da aynı görünür; burada kazanan yoktur.</p>\n<p>WebP, kısmi saydamlıkta da PNG kadar iyidir. Yumuşak kenarlar ve gölgeler iki formatta da temiz kalır.</p>\n<p>Uygulamada fark yoktur. Saydamlık gerektiren bir logoyu hangi formatta saklarsanız saklayın, görsel aynı görünür.</p>\n<h2 id=\"file-size-compared\">Dosya boyutu: WebP açık ara önde</h2>\n<p>Bu kategoride WebP açık ara kazanır. Aynı logonun WebP sürümü, PNG sürümünden genellikle üçte bir daha küçüktür.</p>\n<p>Fark, görsel sayısı arttıkça büyür. Yirmi görselli bir sayfada toplam kazanç birkaç MB olabilir; bu, yüklenme süresinde hissedilir.</p>\n<p>PNG yalnızca çok küçük dosyalarda rekabet eder. Birkaç KB'lık simgelerde WebP'nin başlık bilgisi avantajı silebilir.</p>\n<h2 id=\"text-sharpness\">Metin netliği: PNG az farkla önde</h2>\n<p>Kayıplı WebP, metin kenarlarında hafif bozulma yapabilir. PNG kayıpsız olduğu için yazılar her zaman keskindir.</p>\n<p>Fark, yüksek kalite ayarında küçüktür. Yüzde 85 ve üzeri kalitede çoğu kişi farkı göremez.</p>\n<p>Çok küçük yazılar ya da ince çizgiler için PNG daha güvenlidir. Ekran görüntülerinde metin kritikse PNG'yi ya da yüksek kaliteli WebP'yi tercih edin.</p>\n<h2 id=\"photos-compared\">Fotoğraflar: WebP kesin kazanır</h2>\n<p>Fotoğraflarda WebP, PNG'yi açık ara geçer. PNG fotoğrafları verimsiz saklar; dosyalar devasa olur.</p>\n<p>Fotoğraf benzeri bir PNG, WebP olarak yarıya ya da üçte birine inebilir. Görsel kalite farkı ise gözle görülmez.</p>\n<p>Fotoğraf için PNG kullanmanın nedeni yoktur. WebP yoksa JPG kullanın; PNG fotoğraf için en kötü seçimdir.</p>\n<h2 id=\"browser-support\">Tarayıcı desteği: PNG önde, WebP yetişiyor</h2>\n<p>PNG her tarayıcıda çalışır; otuz yıllık destektir. WebP ise modern tarayıcıların tamamında desteklenir.</p>\n<p>Eski tarayıcı payı artık çok küçüktür. Çoğu site için WebP kullanmak güvenlidir; kalan risk picture öğesiyle kapatılır.</p>\n<p>Picture öğesiyle önce WebP, sonra PNG yedeği sunun. Modern tarayıcılar hızlı sürümü alır, eskiler yedeği kullanır.</p>\n<h2 id=\"other-support\">Tarayıcı dışındaki destek</h2>\n<p>Tarayıcı dışında PNG açık ara öndedir. Ofis programları, e-posta istemcileri ve eski yazılımlar PNG'yi sorunsuz açar.</p>\n<p>WebP, Word ve PowerPoint'in yeni sürümlerinde çalışır ama eski sürümlerde açılmaz. E-posta istemcilerinde de durum karışıktır.</p>\n<p>Dosya tarayıcı dışına çıkacaksa PNG kullanın. Uyumluluk, boyut kazancından önemlidir.</p>\n<h2 id=\"when-to-use-png\">PNG ne zaman kullanılmalı</h2>\n<p>Hedef form, e-posta ya da eski yazılımsa PNG kullanın. Her yerde açılır ve sürpriz yapmaz.</p>\n<p>Çok küçük yazılar içeren ekran görüntülerinde PNG kullanın. Kayıpsız yapı, metni her zaman keskin tutar.</p>\n<p>Arşiv için PNG kullanın. Kayıpsız olduğu için orijinali saklamak için idealdir; WebP arşiv için de olur ama PNG evrenseldir.</p>\n<h2 id=\"when-to-use-webp\">WebP ne zaman kullanılmalı</h2>\n<p>Web sitesi görsellerinde WebP kullanın. Hız kazancı gerçektir ve ziyaretçiler farkı hisseder.</p>\n<p>Saydam logolar ve simgeler için WebP kullanın. Saydamlık korunur ve dosya PNG'den çok daha küçük olur.</p>\n<p>Blog ve e-ticaret görsellerinde WebP kullanın. Onlarca görselin toplam kazancı sayfa hızını belirgin iyileştirir.</p>\n<h2 id=\"converting-between-them\">İkisi arasında dönüştürme</h2>\n<p>PNG'den WebP'ye dönüştürme kolaydır ve kayıpsızdan kayıplıya geçişte kalite ayarı sizin elinizdedir. Yüzde 85 iyi bir başlangıçtır.</p>\n<p>WebP'den PNG'ye dönüştürme de kolaydır ama dosya büyür. Dönüştürmeden önce gerçekten PNG'ye ihtiyacınız olduğundan emin olun.</p>\n<p>Her iki yönde de orijinalleri saklayın. Dönüştürme zinciri kalite kaybettirir; her zaman kaynaktan üretin.</p>\n<h2 id=\"verdict\">Karar: hangi format kazanıyor?</h2>\n<p>Web için WebP kazanıyor. Daha küçük dosyalar, aynı görünüm ve tam tarayıcı desteği; kazanç açık.</p>\n<p>Uyumluluk için PNG kazanıyor. Her yerde açılır ve hiçbir sistem onu reddetmez.</p>\n<p>Doğru cevap ikisini de kullanmaktır. Web için WebP, paylaşım ve arşiv için PNG; format hedefe göre seçilir.</p>\n<h2 id=\"png-webp-email\">E-posta için PNG ve WebP</h2>\n<p>E-postada PNG kullanın. Tüm istemciler PNG'yi güvenilir gösterir; WebP bazı istemcilerde kırık görsel olur.</p>\n<p>E-posta görseli küçük olmalıdır. PNG büyükse önce boyutunu küçültün ya da JPG'ye dönüştürün.</p>\n<p>İmza ve logo için PNG idealdir. Küçük dosyalardır ve her alıcıda aynı görünürler.</p>\n<h2 id=\"png-webp-social\">Sosyal medya için PNG ve WebP</h2>\n<p>Sosyal platformlar yüklenen görseli genellikle kendi formatına çevirir. Yükleme formatı sonucu pek etkilemez.</p>\n<p>Yine de WebP yüklemek daha hızlıdır. Dosya küçük olduğu için yükleme süresi kısalır.</p>\n<p>Platformun istediği boyuta dikkat edin. Yanlış boyut kırpılır; format burada ikincil konudur.</p>\n<h2 id=\"png-webp-print\">Baskı için PNG ve WebP</h2>\n<p>Baskıda PNG kullanın. Baskı merkezleri PNG'yi kabul eder; WebP'yi reddedebilir ya da yanlış işleyebilir.</p>\n<p>Baskı için yüksek çözünürlük gerekir. Format ne olursa olsun, 300 DPI ve üzeri çözünürlük hedefleyin.</p>\n<p>WebP'yi baskıya göndermeden önce PNG'ye dönüştürün. Dönüştürmeyi kendiniz yapın; baskı merkezinin dönüştürmesine bırakmayın.</p>\n<h2 id=\"png-webp-archiving\">Arşiv için PNG ve WebP</h2>\n<p>Arşiv için PNG daha güvenlidir. Kayıpsızdır ve otuz yıldır her sistemde açılır.</p>\n<p>WebP kayıpsız modda da arşivlenebilir ama evrensellik PNG'nindir. On yıl sonra hangi formatın açılacağı belirsizdir; PNG'nin açılacağı kesindir.</p>\n<p>En iyisi orijinali PNG olarak saklamaktır. WebP kopyaları kullanımdan, PNG orijinaller arşivden gelir.</p>\n<h2 id=\"choosing-format-new-website\">Yeni bir web sitesi için format seçmek</h2>\n<p>Yeni bir site kuruyorsanız WebP'yi varsayılan yapın. Modern tarayıcılar destekler ve hız kazancı ilk günden başlar.</p>\n<p>Picture öğesiyle PNG yedeği ekleyin. Bu, eski tarayıcı riskini tamamen ortadan kaldırır.</p>\n<p>Ekibe kuralı yazın: web görselleri WebP, paylaşım dosyaları PNG. Net kural, karışıklığı önler.</p>\n<h2 id=\"png-webp-app-store\">Uygulama mağazası listeleri için PNG ve WebP</h2>\n<p>Uygulama mağazaları genellikle PNG ister. Mağaza listesi için istenen formatı kullanın; kurallara uymak zorunludur.</p>\n<p>Ekran görüntüleri için mağazanın boyut kurallarına uyun. Format kadar boyut da önemlidir.</p>\n<p>Uygulama içi görsellerde WebP kullanabilirsiniz. Mağaza listesi dışındaki görsellerde hız kazancı geçerlidir.</p>\n<p>Sonuç basit: web için WebP, her yer için PNG. Dönüştürmek için <a href=\"/tr/png-webp-ye-donustur\">PNG'den WebP'ye aracını</a> kullanın; adımlar için <a href=\"/tr/blog/png-webp-ye-nasil-donusturulur\">PNG WebP'ye nasıl dönüştürülür</a> yazısına bakın. Kılavuzun tamamı <a href=\"/tr/blog/png-webp-ye-donustur-rehberi\">PNG'den WebP'ye kılavuzunda</a>; ters yön için <a href=\"/tr/webp-png-ye-donustur\">WebP'den PNG'ye dönüştürücü</a> hazırdır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Web sitesindeki logolar için WebP, PNG'den daha mı iyi?","answer":"Evet, çoğu durumda. WebP logonun saydamlığını korur ve dosyayı üçte bir küçültür; görünüm aynı kalır. Yüzde 85 kalite kullanın ve çok eski tarayıcılar için picture öğesiyle PNG yedeği sunun."},{"question":"PNG'yi WebP'ye dönüştürmek kalite kaybettirir mi?","answer":"Çok az. WebP kayıplı modda çalışır ama yüzde 85 ve üzeri kalitede fark gözle görülmez. Saydamlık tamamen korunur. Kayıpsız WebP de mümkündür ama dosyalar daha büyük olur; çoğu kullanımda kayıplı WebP yeterlidir."},{"question":"WebP görsellerini Word ve PowerPoint'te kullanabilir miyim?","answer":"Yeni sürümlerde evet, eski sürümlerde hayır. Office'in güncel sürümleri WebP'yi destekler ama eski sürümler açamaz. Belge başkalarıyla paylaşılacaksa PNG kullanın; yalnızca kendi bilgisayarınızda kullanılacaksa WebP olur."},{"question":"WebP bir gün PNG'nin yerini tamamen alacak mı?","answer":"Web'de büyük ölçüde aldı bile; ama tamamen alması beklenmiyor. PNG otuz yıldır her yerde açılıyor ve arşiv ile uyumluluk için vazgeçilmez. WebP web'in formatı, PNG ise evrensel yedek olmaya devam edecek."},{"question":"Metin içeren ekran görüntüleri için hangi format daha iyi?","answer":"PNG daha güvenlidir, çünkü kayıpsızdır ve yazıları her zaman keskin tutar. Yüksek kaliteli WebP de (yüzde 85 ve üzeri) çoğu durumda yeterlidir; çok küçük yazılar için PNG'yi tercih edin ve her zaman tam boyutta karşılaştırın."},{"question":"Tüm PNG dosyalarımı WebP'ye dönüştürmeli miyim?","answer":"Hayır, yalnızca web'de kullanılacakları dönüştürün. Arşiv, e-posta, form ve baskı için PNG'yi koruyun. Çok küçük simgelerde kazanç olmayabilir; dönüştürmeden önce boyutları karşılaştırın ve yalnızca işe yarayanları çevirin."}];
